import { z } from "zod";
import { OpaqueIdSchema, Sha256Schema, VersionIdSchema } from "./common.ts";

export const PrivateSlideContextSchema = z
  .object({
    privateSlideId: OpaqueIdSchema,
    publicSlideKey: OpaqueIdSchema.nullable(),
    ordinal: z.number().int().positive(),
    speakerNotes: z.string(),
    extractedText: z.string(),
    sourceAssetIds: z.array(OpaqueIdSchema),
  })
  .strict();

export const PrivateDeckContextSchema = z
  .object({
    deckId: OpaqueIdSchema,
    deckVersion: VersionIdSchema,
    manifestHash: Sha256Schema,
    title: z.string().min(1).max(500),
    ownerAccountId: OpaqueIdSchema,
    aclPolicyVersion: VersionIdSchema,
    privateObjectPrefix: z.string().min(1),
    slides: z.array(PrivateSlideContextSchema).min(1),
  })
  .strict();

export const PublishedSlideImageSchema = z
  .object({
    url: z.url(),
    contentHash: Sha256Schema,
    width: z.number().int().positive(),
    height: z.number().int().positive(),
  })
  .strict();

export const PublishedSlideSchema = z
  .object({
    publicSlideKey: OpaqueIdSchema,
    ordinal: z.number().int().positive(),
    image: PublishedSlideImageSchema,
    accessibilityLabel: z.string().min(1).max(1_000),
  })
  .strict();

export const PublishedDeckArtifactSchema = z
  .object({
    deckVersion: VersionIdSchema,
    manifestHash: Sha256Schema,
    title: z.string().min(1).max(500),
    slides: z.array(PublishedSlideSchema).min(1),
  })
  .strict();

export type PrivateDeckContext = z.infer<typeof PrivateDeckContextSchema>;
export type PublishedDeckArtifact = z.infer<typeof PublishedDeckArtifactSchema>;

import { z } from "zod";
import {
  EpochSchema,
  OpaqueIdSchema,
  PublicSlideOccurrenceSchema,
  RevisionSchema,
  Sha256Schema,
  TimestampMsSchema,
  VersionIdSchema,
} from "./common.ts";

export const SourceRevisionSchema = z
  .object({
    sourceId: OpaqueIdSchema,
    revision: VersionIdSchema,
    contentHash: Sha256Schema,
  })
  .strict();

export const DecisionVersionsSchema = z
  .object({
    acl: VersionIdSchema,
    publicationPolicy: VersionIdSchema,
    rights: VersionIdSchema,
    dlp: VersionIdSchema,
  })
  .strict();

export const CausalEnvelopeSchema = z
  .object({
    presentationSessionId: OpaqueIdSchema,
    presentationSessionEpoch: EpochSchema,
    displayBindingEpoch: EpochSchema,
    deckVersion: VersionIdSchema,
    manifestHash: Sha256Schema,
    occurrence: PublicSlideOccurrenceSchema,
    transcriptFinalId: OpaqueIdSchema,
    source: SourceRevisionSchema,
    decisions: DecisionVersionsSchema,
  })
  .strict();

export const EvidenceCandidateSchema = z
  .object({
    candidateId: OpaqueIdSchema,
    candidateVersion: VersionIdSchema,
    provenance: z.enum(["CURATED_PREAPPROVED", "LIVE_VERIFIED"]),
    verdict: z.literal("SUPPORTED"),
    claimText: z.string().min(1),
    evidenceExcerpt: z.string().min(1),
    privateSourceUri: z.string().min(1),
    causal: CausalEnvelopeSchema,
  })
  .strict();

export const PublishedAudienceCardSchema = z
  .object({
    projectionId: OpaqueIdSchema,
    status: z.literal("PUBLISHED"),
    claim: z.string().min(1).max(2_000),
    supportSummary: z.string().min(1).max(4_000),
    sourceLabel: z.string().min(1).max(500),
    publishedAtMs: TimestampMsSchema,
    expiresAtMs: TimestampMsSchema.nullable(),
    publicCardRevision: RevisionSchema,
    deckVersion: VersionIdSchema,
    manifestHash: Sha256Schema,
    occurrence: PublicSlideOccurrenceSchema,
  })
  .strict();

export const PublicationTombstoneSchema = z
  .object({
    projectionId: OpaqueIdSchema,
    status: z.enum(["RETRACTED", "EXPIRED"]),
    publicCardRevision: RevisionSchema,
    occurredAtMs: TimestampMsSchema,
  })
  .strict();

const PublicationMutationHeaderSchema = z
  .object({
    presentationSessionId: OpaqueIdSchema,
    presentationSessionEpoch: EpochSchema,
    actorId: OpaqueIdSchema,
    authorityId: OpaqueIdSchema,
    commandId: OpaqueIdSchema,
    requestHash: Sha256Schema,
    expectedRevision: RevisionSchema,
  })
  .strict();

export const ApprovePublicationSchema = PublicationMutationHeaderSchema.extend({
  type: z.literal("APPROVE"),
  candidateId: OpaqueIdSchema,
  candidateVersion: VersionIdSchema,
}).strict();

export const RetractPublicationSchema = PublicationMutationHeaderSchema.extend({
  type: z.literal("RETRACT"),
  projectionId: OpaqueIdSchema,
}).strict();

export const ExpirePublicationSchema = PublicationMutationHeaderSchema.extend({
  type: z.literal("EXPIRE"),
  projectionId: OpaqueIdSchema,
}).strict();

export const PublicationMutationSchema = z.discriminatedUnion("type", [
  ApprovePublicationSchema,
  RetractPublicationSchema,
  ExpirePublicationSchema,
]);

export type CausalEnvelope = z.infer<typeof CausalEnvelopeSchema>;
export type EvidenceCandidate = z.infer<typeof EvidenceCandidateSchema>;
export type PublishedAudienceCard = z.infer<typeof PublishedAudienceCardSchema>;
export type PublicationTombstone = z.infer<typeof PublicationTombstoneSchema>;
export type PublicationMutation = z.infer<typeof PublicationMutationSchema>;

import { z } from "zod";
import {
  EpochSchema,
  OpaqueIdSchema,
  PublicSlideOccurrenceSchema,
  RevisionSchema,
  Sha256Schema,
  TimestampMsSchema,
  VersionIdSchema,
} from "./common.ts";
import { PrivateDeckContextSchema, PublishedDeckArtifactSchema } from "./deck.ts";
import {
  EvidenceCandidateSchema,
  PublishedAudienceCardSchema,
  PublicationTombstoneSchema,
} from "./publication.ts";

export const ProtocolRangeSchema = z
  .object({
    min: z.number().int().nonnegative(),
    max: z.number().int().nonnegative(),
  })
  .strict()
  .refine(({ min, max }) => min <= max, { message: "protocol min must not exceed max" });

export const BuildHandshakeSchema = z
  .object({
    releaseId: VersionIdSchema,
    protocolRange: ProtocolRangeSchema,
    buildId: VersionIdSchema,
  })
  .strict();

export type BuildHandshake = z.infer<typeof BuildHandshakeSchema>;
export type HandshakeCompatibility =
  | { compatible: true; protocolVersion: number }
  | { compatible: false; reason: "RELEASE_MISMATCH" | "PROTOCOL_RANGE_MISMATCH" };

export function checkHandshakeCompatibility(
  client: BuildHandshake,
  server: BuildHandshake,
): HandshakeCompatibility {
  if (client.releaseId !== server.releaseId) {
    return { compatible: false, reason: "RELEASE_MISMATCH" };
  }
  const lowestMaximum = Math.min(client.protocolRange.max, server.protocolRange.max);
  const highestMinimum = Math.max(client.protocolRange.min, server.protocolRange.min);
  if (lowestMaximum < highestMinimum) {
    return { compatible: false, reason: "PROTOCOL_RANGE_MISMATCH" };
  }
  return { compatible: true, protocolVersion: lowestMaximum };
}

export const PlaybackControlLeaseSchema = z
  .object({
    leaseId: OpaqueIdSchema,
    actorId: OpaqueIdSchema,
    controllerEpoch: EpochSchema,
    expiresAtMs: TimestampMsSchema,
  })
  .strict();

export const PublicationAuthoritySchema = z
  .object({
    authorityId: OpaqueIdSchema,
    actorId: OpaqueIdSchema,
    policyVersion: VersionIdSchema,
    expiresAtMs: TimestampMsSchema,
  })
  .strict();

export const AudienceDisplaySessionSchema = z
  .object({
    audienceDisplaySessionId: OpaqueIdSchema,
    displayId: OpaqueIdSchema,
    displayBindingEpoch: EpochSchema,
    expiresAtMs: TimestampMsSchema,
  })
  .strict();

const SessionIdentityShape = {
  presentationSessionId: OpaqueIdSchema,
  presentationSessionEpoch: EpochSchema,
} as const;

export const ControllerSessionSchema = z
  .object({
    role: z.literal("CONTROLLER"),
    ...SessionIdentityShape,
    actorId: OpaqueIdSchema,
    lease: PlaybackControlLeaseSchema,
  })
  .strict();

export const PublicStageSessionSchema = z
  .object({
    role: z.literal("PUBLIC_STAGE"),
    ...SessionIdentityShape,
    display: AudienceDisplaySessionSchema,
  })
  .strict();

export const PublisherSessionSchema = z
  .object({
    role: z.literal("PUBLISHER"),
    ...SessionIdentityShape,
    actorId: OpaqueIdSchema,
    authority: PublicationAuthoritySchema,
  })
  .strict();

export const RoleSessionSchema = z.discriminatedUnion("role", [
  ControllerSessionSchema,
  PublicStageSessionSchema,
  PublisherSessionSchema,
]);

export const RoleSchema = z.enum(["CONTROLLER", "PUBLIC_STAGE", "PUBLISHER"]);
export const TopicSchema = z.enum([
  "PRESENTER_CONTROL",
  "PRIVATE_CANDIDATES",
  "PUBLIC_PLAYBACK",
  "PUBLIC_CARDS",
  "DISPLAY_RECEIPTS",
]);
export const TopicActionSchema = z.enum(["READ", "WRITE"]);

const allowedRoleActions = new Set<string>([
  "CONTROLLER:PRESENTER_CONTROL:READ",
  "CONTROLLER:PRESENTER_CONTROL:WRITE",
  "CONTROLLER:PRIVATE_CANDIDATES:READ",
  "CONTROLLER:DISPLAY_RECEIPTS:READ",
  "PUBLISHER:PRIVATE_CANDIDATES:READ",
  "PUBLISHER:PRIVATE_CANDIDATES:WRITE",
  "PUBLISHER:PUBLIC_CARDS:READ",
  "PUBLISHER:PUBLIC_CARDS:WRITE",
  "PUBLIC_STAGE:PUBLIC_PLAYBACK:READ",
  "PUBLIC_STAGE:PUBLIC_CARDS:READ",
  "PUBLIC_STAGE:DISPLAY_RECEIPTS:WRITE",
]);

export function authorizeRoleAction(role: unknown, topic: unknown, action: unknown): boolean {
  const parsedRole = RoleSchema.safeParse(role);
  const parsedTopic = TopicSchema.safeParse(topic);
  const parsedAction = TopicActionSchema.safeParse(action);
  if (!(parsedRole.success && parsedTopic.success && parsedAction.success)) return false;
  return allowedRoleActions.has(`${parsedRole.data}:${parsedTopic.data}:${parsedAction.data}`);
}

const PlaybackCommandHeaderShape = {
  ...SessionIdentityShape,
  actorId: OpaqueIdSchema,
  controllerEpoch: EpochSchema,
  commandId: OpaqueIdSchema,
