import { describe, expect, test } from "bun:test";
import {
  PublishedAudienceCardSchema,
  authorizeRoleAction,
  type PlaybackCommand,
} from "@impromptu/contracts";
import {
  playbackAuthorityFixture,
  playbackCommandFixture,
  PROTOCOL_TRANSITION_MATRIX,
  runPlaybackFaultSchedule,
  runPublicProjectionFaultSchedule,
  type PlaybackFaultAction,
  type PlaybackIntent,
  type PublicProjectionFaultAction,
} from "@impromptu/test-harness";
import {
  createPublicationState,
  initialPublicPlaybackState,
  reducePublication,
  type PublicationOperation,
  type PublicPlaybackEvent,
} from "@impromptu/state";
import fc from "fast-check";

const propertyParameters = { seed: 0x1a2b3c, numRuns: 250 } as const;
const manifestHash = "a".repeat(64);

const playbackIntentArbitrary: fc.Arbitrary<PlaybackIntent> = fc.oneof(
  fc.record({
    type: fc.constant("SLIDE_SET" as const),
    publicSlideKey: fc.constantFrom("slide-1", "slide-2", "slide-3"),
  }),
  fc.record({
    type: fc.constant("BLACKOUT_SET" as const),
    enabled: fc.boolean(),
  }),
);

function commandSchedule(commands: readonly PlaybackCommand[]): PlaybackFaultAction[] {
  return [
    ...commands.map((command): PlaybackFaultAction => ({ type: "COMMAND", command })),
    ...commands.map(
      (command): PlaybackFaultAction => ({
        type: "STAGE_APPLY",
        commandId: command.commandId,
        displayBindingEpoch: 1,
      }),
    ),
  ];
}

describe("generated authority fault schedules", () => {
  test("duplicates and restart placement never change the terminal authority state", () => {
    fc.assert(
      fc.property(
        fc.array(playbackIntentArbitrary, { minLength: 1, maxLength: 40 }),
        fc.array(fc.nat(200), { maxLength: 80 }),
        fc.array(fc.boolean(), { minLength: 1, maxLength: 40 }),
        (intents, duplicateIndexes, restartFlags) => {
          const commands = intents.map((intent, index) =>
            playbackCommandFixture(index + 1, intent),
          );
          const faulted: PlaybackFaultAction[] = [];
          for (const [index, command] of commands.entries()) {
            faulted.push({ type: "COMMAND", command });
            if (restartFlags[index % restartFlags.length]) faulted.push({ type: "RESTART" });
          }
          for (const index of duplicateIndexes) {
            const duplicate = commands[index % commands.length];
            if (duplicate !== undefined) faulted.push({ type: "COMMAND", command: duplicate });
          }
          for (const command of commands) {
            faulted.push({
              type: "STAGE_APPLY",
              commandId: command.commandId,
              displayBindingEpoch: 1,
            });
          }
          for (const index of duplicateIndexes) {
            const duplicate = commands[index % commands.length];
            if (duplicate !== undefined) {
              faulted.push({
                type: "STAGE_APPLY",
                commandId: duplicate.commandId,
                displayBindingEpoch: 1,
              });
            }
          }

          const baseline = runPlaybackFaultSchedule(
            playbackAuthorityFixture(),
            commandSchedule(commands),
          );
          const first = runPlaybackFaultSchedule(playbackAuthorityFixture(), faulted);
          const replay = runPlaybackFaultSchedule(playbackAuthorityFixture(), faulted);

          expect(first).toEqual(replay);
          expect(first.state).toEqual(baseline.state);
          expect(first.state.controlRevision).toBe(commands.length);
          expect(first.state.publicPlaybackRevision).toBe(commands.length);
        },
      ),
      propertyParameters,
    );
  });
});

describe("generated public projection fault schedules", () => {
  const initial = initialPublicPlaybackState({
    presentationSessionId: "session-1",
    presentationSessionEpoch: 1,
    displayBindingEpoch: 1,
    deckVersion: "deck-v1",
    manifestHash,
    occurrence: { publicSlideKey: "slide-1", occurrenceSeq: 1 },
    blackout: false,
  });
  const events: readonly PublicPlaybackEvent[] = Array.from({ length: 12 }, (_, index) => ({
    ...initial,
    publicPlaybackRevision: index + 1,
    occurrence: {
      publicSlideKey: `slide-${(index % 3) + 1}`,
      occurrenceSeq: index + 2,
    },
    blackout: index % 2 === 1,
  }));
  const finalSnapshot = events[events.length - 1];
  if (finalSnapshot === undefined) throw new Error("generated event fixture cannot be empty");

  test("out-of-order, gap, duplicate, partition, and restart schedules converge via snapshot", () => {
    fc.assert(
      fc.property(
        fc.array(
          fc.record({
            eventIndex: fc.integer({ min: 0, max: events.length - 1 }),
            partitioned: fc.boolean(),
            restart: fc.boolean(),
          }),
          { maxLength: 100 },
        ),
        (deliveries) => {
          const schedule: PublicProjectionFaultAction[] = [];
          for (const delivery of deliveries) {
            schedule.push({ type: "PARTITION", active: delivery.partitioned });
            const event = events[delivery.eventIndex];
            if (event !== undefined) schedule.push({ type: "EVENT", event });
            schedule.push({ type: "PARTITION", active: false });
            if (delivery.restart) schedule.push({ type: "RESTART" });
          }
          schedule.push({ type: "SNAPSHOT", snapshot: finalSnapshot });

          const first = runPublicProjectionFaultSchedule(initial, schedule);
          const replay = runPublicProjectionFaultSchedule(initial, schedule);
          expect(first).toEqual(replay);
          expect(first.state).toEqual(finalSnapshot);
        },
      ),
      propertyParameters,
    );
  });
});

describe("generated publication CAS schedules", () => {
  const qualify: PublicationOperation = {
    type: "QUALIFY",
    commandId: "qualify",
    requestHash: "1".repeat(64),
    expectedRevision: 0,
  };
  const approve: PublicationOperation = {
    type: "APPROVE",
    commandId: "approve",
    requestHash: "2".repeat(64),
    expectedRevision: 1,
    candidateVersion: "candidate-v1",
    projectionId: "projection-1",
  };
  const retractAtSameCas: PublicationOperation = {
    type: "RETRACT",
    commandId: "retract",
    requestHash: "3".repeat(64),
    expectedRevision: 1,
    projectionId: "projection-1",
  };

  test("concurrent approve/retract order has one legal winner and a stable terminal state", () => {
    fc.assert(
      fc.property(fc.boolean(), fc.array(fc.boolean(), { maxLength: 30 }), (approveFirst, retries) => {
        let state = reducePublication(
          createPublicationState("candidate-1", "candidate-v1"),
          qualify,
        ).state;
        const concurrent = approveFirst ? [approve, retractAtSameCas] : [retractAtSameCas, approve];
        for (const operation of concurrent) state = reducePublication(state, operation).state;
        for (const retryApprove of retries) {
          state = reducePublication(state, retryApprove ? approve : retractAtSameCas).state;
        }

        expect(state.status).toBe("PUBLISHED");
        expect(state.revision).toBe(2);
        expect(state.projectionId).toBe("projection-1");
      }),
      propertyParameters,
    );
  });
});

