import type {
  AcceptedCommandReceipt,
  CommandReceipt,
  PlaybackCommand,
  PublicSlideOccurrence,
  RejectedCommandReceipt,
  StageAppliedReceipt,
} from "@impromptu/contracts";

export type StageStatus = "READY" | "DISCONNECTED" | "UNBOUND";

export type PlaybackEffect = Readonly<{
  commandId: string;
  acceptedControlRevision: number;
  occurrence: PublicSlideOccurrence;
  blackout: boolean;
}>;

type AcceptedCommandRecord = Readonly<{
  requestHash: string;
  receipt: AcceptedCommandReceipt;
  effect: PlaybackEffect;
  appliedReceipt: StageAppliedReceipt | null;
}>;

export type PlaybackAuthorityState = Readonly<{
  presentationSessionId: string;
  presentationSessionEpoch: number;
  actorId: string;
  controllerEpoch: number;
  displayBindingEpoch: number;
  controlRevision: number;
  publicPlaybackRevision: number;
  stageStatus: StageStatus;
  slideOrder: readonly string[];
  occurrence: PublicSlideOccurrence;
  nextOccurrenceSeq: number;
  blackout: boolean;
  acceptedCommands: Readonly<Record<string, AcceptedCommandRecord>>;
}>;

export type PlaybackAuthoritySnapshot = PlaybackAuthorityState;

export type CreatePlaybackAuthorityState = Readonly<{
  presentationSessionId: string;
  presentationSessionEpoch: number;
  actorId: string;
  controllerEpoch: number;
  displayBindingEpoch: number;
  stageStatus: StageStatus;
  slideOrder: readonly string[];
  initialSlideKey: string;
}>;

export function createPlaybackAuthorityState(
  input: CreatePlaybackAuthorityState,
): PlaybackAuthorityState {
  if (!input.slideOrder.includes(input.initialSlideKey)) {
    throw new Error("initial slide must exist in slide order");
  }
  if (new Set(input.slideOrder).size !== input.slideOrder.length) {
    throw new Error("slide order must contain unique public slide keys");
  }
  return {
    ...input,
    slideOrder: [...input.slideOrder],
    controlRevision: 0,
    publicPlaybackRevision: 0,
    occurrence: { publicSlideKey: input.initialSlideKey, occurrenceSeq: 1 },
    nextOccurrenceSeq: 2,
    blackout: false,
    acceptedCommands: {},
  };
}

function commandKey(command: PlaybackCommand): string {
  return JSON.stringify([
    command.presentationSessionId,
    command.actorId,
    command.controllerEpoch,
    command.commandId,
  ]);
}

function receiptIdentity(command: PlaybackCommand) {
  return {
    presentationSessionId: command.presentationSessionId,
    presentationSessionEpoch: command.presentationSessionEpoch,
    actorId: command.actorId,
    controllerEpoch: command.controllerEpoch,
    commandId: command.commandId,
    requestHash: command.requestHash,
  };
}

function reject(
  state: PlaybackAuthorityState,
  command: PlaybackCommand,
  reason: RejectedCommandReceipt["reason"],
): PlaybackReduction {
  return {
    state,
    receipt: { status: "REJECTED", ...receiptIdentity(command), reason },
    effect: null,
  };
}

function isRelative(command: PlaybackCommand): boolean {
  return command.type === "SLIDE_NEXT" || command.type === "SLIDE_PREVIOUS";
}

function targetSlide(state: PlaybackAuthorityState, command: PlaybackCommand): string | null {
  if (command.type === "SLIDE_SET") {
    return state.slideOrder.includes(command.publicSlideKey) ? command.publicSlideKey : null;
  }
  if (!isRelative(command)) return state.occurrence.publicSlideKey;
  const currentIndex = state.slideOrder.indexOf(state.occurrence.publicSlideKey);
  const offset = command.type === "SLIDE_NEXT" ? 1 : -1;
  return state.slideOrder[currentIndex + offset] ?? null;
}

export type PlaybackReduction = Readonly<{
  state: PlaybackAuthorityState;
  receipt: CommandReceipt;
  effect: PlaybackEffect | null;
}>;

export function reducePlaybackCommand(
  state: PlaybackAuthorityState,
  command: PlaybackCommand,
): PlaybackReduction {
  if (
    command.presentationSessionId !== state.presentationSessionId ||
    command.presentationSessionEpoch !== state.presentationSessionEpoch
  ) {
    return reject(state, command, "STALE_SESSION_EPOCH");
  }
  if (command.actorId !== state.actorId || command.controllerEpoch !== state.controllerEpoch) {
    return reject(state, command, "STALE_CONTROLLER_EPOCH");
  }

  const key = commandKey(command);
  const prior = state.acceptedCommands[key];
  if (prior !== undefined) {
    if (prior.requestHash !== command.requestHash) {
      return reject(state, command, "IDEMPOTENCY_CONFLICT");
    }
    return { state, receipt: prior.receipt, effect: prior.effect };
  }
  if (command.baseRevision !== state.controlRevision) {
    return reject(state, command, "REVISION_MISMATCH");
  }
  if (isRelative(command) && command.delivery === "OFFLINE_REPLAY") {
    return reject(state, command, "OFFLINE_RELATIVE_COMMAND");
  }
  if (isRelative(command) && state.stageStatus !== "READY") {
    return reject(state, command, "STAGE_NOT_READY");
  }

  const nextSlide = targetSlide(state, command);
  if (nextSlide === null) {
    const reason = command.type === "SLIDE_SET" ? "UNKNOWN_SLIDE" : "SLIDE_BOUNDARY";
    return reject(state, command, reason);
  }

  const slideChanged = nextSlide !== state.occurrence.publicSlideKey;
  const occurrence = slideChanged
    ? { publicSlideKey: nextSlide, occurrenceSeq: state.nextOccurrenceSeq }
    : state.occurrence;
  const nextOccurrenceSeq = slideChanged ? state.nextOccurrenceSeq + 1 : state.nextOccurrenceSeq;
  const blackout = command.type === "BLACKOUT_SET" ? command.enabled : state.blackout;
  const acceptedControlRevision = state.controlRevision + 1;
  const receipt: AcceptedCommandReceipt = {
    status: "ACCEPTED",
    ...receiptIdentity(command),
    acceptedControlRevision,
  };
  const effect: PlaybackEffect = {
    commandId: command.commandId,
    acceptedControlRevision,
    occurrence,
    blackout,
  };
  const record: AcceptedCommandRecord = {
    requestHash: command.requestHash,
    receipt,
    effect,
    appliedReceipt: null,
  };
  return {
    state: {
      ...state,
      controlRevision: acceptedControlRevision,
      occurrence,
      nextOccurrenceSeq,
      blackout,
      acceptedCommands: { ...state.acceptedCommands, [key]: record },
    },
    receipt,
    effect,
  };
}

export type StageApplyOutcome =
  | "APPLIED"
  | "DUPLICATE"
  | "OUT_OF_ORDER"
  | "UNKNOWN_COMMAND"
  | "STALE_BINDING";

export type StageApplyResult = Readonly<{
  state: PlaybackAuthorityState;
  outcome: StageApplyOutcome;
  receipt: StageAppliedReceipt | null;
}>;

export function markStageApplied(
  state: PlaybackAuthorityState,
  commandId: string,
  displayBindingEpoch: number,
): StageApplyResult {
  if (displayBindingEpoch !== state.displayBindingEpoch) {
    return { state, outcome: "STALE_BINDING", receipt: null };
  }
  const key = JSON.stringify([
    state.presentationSessionId,
    state.actorId,
    state.controllerEpoch,
    commandId,
  ]);
  const record = state.acceptedCommands[key];
  if (record === undefined) return { state, outcome: "UNKNOWN_COMMAND", receipt: null };
  if (record.appliedReceipt !== null) {
    return { state, outcome: "DUPLICATE", receipt: record.appliedReceipt };
  }

  const firstPendingRevision = Object.values(state.acceptedCommands)
    .filter(
      (candidate) =>
        candidate.appliedReceipt === null &&
        candidate.receipt.actorId === state.actorId &&
        candidate.receipt.controllerEpoch === state.controllerEpoch,
    )
    .reduce(
      (minimum, candidate) => Math.min(minimum, candidate.receipt.acceptedControlRevision),
      Number.POSITIVE_INFINITY,
    );
  if (record.receipt.acceptedControlRevision !== firstPendingRevision) {
    return { state, outcome: "OUT_OF_ORDER", receipt: null };
  }

  const receipt: StageAppliedReceipt = {
    status: "STAGE_APPLIED",
    presentationSessionId: record.receipt.presentationSessionId,
    presentationSessionEpoch: record.receipt.presentationSessionEpoch,
    actorId: record.receipt.actorId,
    controllerEpoch: record.receipt.controllerEpoch,
    commandId: record.receipt.commandId,
    requestHash: record.receipt.requestHash,
    acceptedControlRevision: record.receipt.acceptedControlRevision,
    publicPlaybackRevision: state.publicPlaybackRevision + 1,
    displayBindingEpoch,
  };
  return {
    state: {
      ...state,
      publicPlaybackRevision: receipt.publicPlaybackRevision,
      acceptedCommands: {
        ...state.acceptedCommands,
        [key]: { ...record, appliedReceipt: receipt },
      },
    },
    outcome: "APPLIED",
    receipt,
  };
}

export function snapshotPlaybackAuthority(
  state: PlaybackAuthorityState,
): PlaybackAuthoritySnapshot {
  return structuredClone(state);
}

export function restorePlaybackAuthority(
  snapshot: PlaybackAuthoritySnapshot,
): PlaybackAuthorityState {
  return structuredClone(snapshot);
}

import type { AudienceSnapshot, PublicSlideOccurrence } from "@impromptu/contracts";

export type PublicPlaybackState = Readonly<{
  presentationSessionId: string;
  presentationSessionEpoch: number;
  displayBindingEpoch: number;
  deckVersion: string;
  manifestHash: string;
  publicPlaybackRevision: number;
  occurrence: PublicSlideOccurrence;
  blackout: boolean;
}>;

export type PublicPlaybackEvent = PublicPlaybackState;
export type PublicPlaybackSnapshot = PublicPlaybackState;

export type InitialPublicPlaybackState = Omit<PublicPlaybackState, "publicPlaybackRevision">;

export function initialPublicPlaybackState(input: InitialPublicPlaybackState): PublicPlaybackState {
  return { ...input, publicPlaybackRevision: 0 };
}

export type PublicPlaybackOutcome =
  | "APPLIED"
  | "DUPLICATE"
  | "GAP_REQUIRES_SNAPSHOT"
  | "STALE_OR_CONFLICTING"
  | "STALE_CAUSAL_ENVELOPE"
  | "STALE_SNAPSHOT";

export type PublicPlaybackResult = Readonly<{
  state: PublicPlaybackState;
  outcome: PublicPlaybackOutcome;
}>;

function sameCausalIdentity(state: PublicPlaybackState, incoming: PublicPlaybackState): boolean {
  return (
    state.presentationSessionId === incoming.presentationSessionId &&
    state.presentationSessionEpoch === incoming.presentationSessionEpoch &&
    state.displayBindingEpoch === incoming.displayBindingEpoch &&
    state.deckVersion === incoming.deckVersion &&
    state.manifestHash === incoming.manifestHash
  );
}

function sameVisibleState(state: PublicPlaybackState, incoming: PublicPlaybackState): boolean {
  return (
    state.occurrence.publicSlideKey === incoming.occurrence.publicSlideKey &&
    state.occurrence.occurrenceSeq === incoming.occurrence.occurrenceSeq &&
    state.blackout === incoming.blackout
  );
}

export function applyPublicPlaybackEvent(
  state: PublicPlaybackState,
  event: PublicPlaybackEvent,
): PublicPlaybackResult {
  if (!sameCausalIdentity(state, event)) {
    return { state, outcome: "STALE_CAUSAL_ENVELOPE" };
  }
  if (event.publicPlaybackRevision === state.publicPlaybackRevision) {
    return {
      state,
      outcome: sameVisibleState(state, event) ? "DUPLICATE" : "STALE_OR_CONFLICTING",
    };
  }
  if (event.publicPlaybackRevision < state.publicPlaybackRevision) {
    return { state, outcome: "STALE_OR_CONFLICTING" };
  }
  if (event.publicPlaybackRevision !== state.publicPlaybackRevision + 1) {
    return { state, outcome: "GAP_REQUIRES_SNAPSHOT" };
  }
  return { state: structuredClone(event), outcome: "APPLIED" };
}

export function applyAudiencePlaybackSnapshot(
  state: PublicPlaybackState,
  snapshot: AudienceSnapshot,
): PublicPlaybackResult {
  return applyPublicPlaybackSnapshot(state, {
    presentationSessionId: snapshot.presentationSessionId,
    presentationSessionEpoch: snapshot.presentationSessionEpoch,
    displayBindingEpoch: snapshot.displayBindingEpoch,
    deckVersion: snapshot.deck.deckVersion,
    manifestHash: snapshot.deck.manifestHash,
    publicPlaybackRevision: snapshot.publicPlaybackRevision,
    occurrence: snapshot.occurrence,
    blackout: snapshot.blackout,
  });
}

export function applyPublicPlaybackSnapshot(
  state: PublicPlaybackState,
  snapshot: PublicPlaybackSnapshot,
): PublicPlaybackResult {
  if (snapshot.presentationSessionId !== state.presentationSessionId) {
    return { state, outcome: "STALE_CAUSAL_ENVELOPE" };
  }
  if (snapshot.presentationSessionEpoch < state.presentationSessionEpoch) {
    return { state, outcome: "STALE_SNAPSHOT" };
  }
  if (
    snapshot.presentationSessionEpoch === state.presentationSessionEpoch &&
    !sameCausalIdentity(state, snapshot)
  ) {
    return { state, outcome: "STALE_CAUSAL_ENVELOPE" };
  }
  if (
    snapshot.presentationSessionEpoch === state.presentationSessionEpoch &&
    snapshot.publicPlaybackRevision < state.publicPlaybackRevision
  ) {
    return { state, outcome: "STALE_SNAPSHOT" };
  }
  return { state: structuredClone(snapshot), outcome: "APPLIED" };
}

export type PublicationStatus = "PRIVATE" | "ELIGIBLE" | "PUBLISHED" | "RETRACTED" | "EXPIRED";
export type PublicationOperationType = "QUALIFY" | "APPROVE" | "RETRACT" | "EXPIRE";

export const PUBLICATION_TRANSITIONS = {
  PRIVATE: ["QUALIFY"],
  ELIGIBLE: ["APPROVE"],
  PUBLISHED: ["RETRACT", "EXPIRE"],
  RETRACTED: [],
  EXPIRED: [],
} as const satisfies Record<PublicationStatus, readonly PublicationOperationType[]>;

type PublicationOperationHeader = Readonly<{
  commandId: string;
  requestHash: string;
  expectedRevision: number;
}>;

export type PublicationOperation =
  | (PublicationOperationHeader & Readonly<{ type: "QUALIFY" }>)
  | (PublicationOperationHeader &
      Readonly<{
        type: "APPROVE";
        candidateVersion: string;
        projectionId: string;
      }>)
  | (PublicationOperationHeader &
      Readonly<{
        type: "RETRACT" | "EXPIRE";
        projectionId: string;
      }>);

export type PublicationAccepted = Readonly<{
  outcome: "ACCEPTED";
  revision: number;
  status: PublicationStatus;
}>;
export type PublicationRejected = Readonly<{
  outcome: "REJECTED";
  reason:
    | "CAS_CONFLICT"
    | "ILLEGAL_TRANSITION"
    | "IDEMPOTENCY_CONFLICT"
    | "CANDIDATE_VERSION_MISMATCH"
    | "PROJECTION_MISMATCH";
}>;
export type PublicationResult = PublicationAccepted | PublicationRejected;

type AcceptedPublicationRecord = Readonly<{
  requestHash: string;
  result: PublicationAccepted;
}>;

export type PublicationState = Readonly<{
  candidateId: string;
  candidateVersion: string;
  projectionId: string | null;
  status: PublicationStatus;
  revision: number;
  acceptedOperations: Readonly<Record<string, AcceptedPublicationRecord>>;
}>;

export function createPublicationState(
  candidateId: string,
  candidateVersion: string,
): PublicationState {
  return {
    candidateId,
    candidateVersion,
    projectionId: null,
    status: "PRIVATE",
    revision: 0,
    acceptedOperations: {},
  };
}

export type PublicationReduction = Readonly<{
  state: PublicationState;
  result: PublicationResult;
}>;

function rejected(
  state: PublicationState,
  reason: PublicationRejected["reason"],
): PublicationReduction {
  return { state, result: { outcome: "REJECTED", reason } };
}

function isLegal(status: PublicationStatus, type: PublicationOperationType): boolean {
  const transitions: readonly PublicationOperationType[] = PUBLICATION_TRANSITIONS[status];
  return transitions.includes(type);
}

export function reducePublication(
  state: PublicationState,
  operation: PublicationOperation,
): PublicationReduction {
  const prior = state.acceptedOperations[operation.commandId];
  if (prior !== undefined) {
    if (prior.requestHash !== operation.requestHash) {
      return rejected(state, "IDEMPOTENCY_CONFLICT");
    }
    return { state, result: prior.result };
  }
  if (operation.expectedRevision !== state.revision) {
    return rejected(state, "CAS_CONFLICT");
  }
  if (!isLegal(state.status, operation.type)) {
    return rejected(state, "ILLEGAL_TRANSITION");
  }
  if (operation.type === "APPROVE" && operation.candidateVersion !== state.candidateVersion) {
    return rejected(state, "CANDIDATE_VERSION_MISMATCH");
  }
  if (
    (operation.type === "RETRACT" || operation.type === "EXPIRE") &&
    operation.projectionId !== state.projectionId
  ) {
    return rejected(state, "PROJECTION_MISMATCH");
  }

  const status: PublicationStatus =
    operation.type === "QUALIFY"
      ? "ELIGIBLE"
      : operation.type === "APPROVE"
        ? "PUBLISHED"
        : operation.type === "RETRACT"
          ? "RETRACTED"
          : "EXPIRED";
  const revision = state.revision + 1;
  const result: PublicationAccepted = { outcome: "ACCEPTED", revision, status };
  const projectionId = operation.type === "APPROVE" ? operation.projectionId : state.projectionId;
  return {
    state: {
      ...state,
      status,
      revision,
      projectionId,
      acceptedOperations: {
        ...state.acceptedOperations,
        [operation.commandId]: { requestHash: operation.requestHash, result },
      },
    },
    result,
  };
}

