          ...entry[1],
          supersededReceipt: {
            ...entry[1].supersededReceipt,
            supersededByControllerEpoch: controllerEpoch,
          },
        },
      },
    };
    expect(() => restorePlaybackAuthority(forged)).not.toThrow();
    expect(restorePlaybackAuthority(forged)).toEqual({ outcome: "INVALID_SNAPSHOT" });
  }
});

